const Event=require("../../models/eventsModel"),getUser=require("../../utilities/user_general_methods")["getUser"],getCurrentDate=require("./userUtils")["getCurrentDate"],eventResults=async n=>{if(n?.events?.length)for(const d of n.events)if(d?.id){let t="";var e=getCurrentDate();const i=await Event.findById({_id:d.id});if(i&&e>i.endDate){let e=0;for(const s of i.sides)s.points>e&&(e=s.points,t=s._id);for(const o of i.prizes)o.message={en:i.eventName.en+" Event",ar:"تحدي "+i.eventName.ar};t.toString()===d.yourSide.toString()&&(n.prizes=[...n.prizes,...i.prizes]),n.events=n.events.filter(e=>e?.id&&e.id.toString()!==i._id.toString())}}return n},addPointsToEvents=async(e,t,n)=>{var d=e.find(e=>e.id.toString()===t)?.yourSide,e=await Event.findById({_id:t}),i=getCurrentDate();if(e&&i<=e.endDate){e.total_points+=n;for(const s of e.sides)d===s._id.toString()&&(s.points+=n);await Event.findByIdAndUpdate({_id:t},e)}},add_event_to_user=async(n,d,i)=>{const s={id:n.body.eventId,yourSide:n.body.sideId,endDate:n.body.endDate,gamesPlayed:0};Event.findById({_id:n.body.eventId}).then(e=>{for(const t of e.sides)t._id.toString()===n.body.sideId&&(t.numberOfPlayers+=1,Event.findByIdAndUpdate({_id:n.body.eventId},e).then(()=>{getUser(n.params.id,{$inc:{coins:-n.body.price},$push:{events:s}},d,i)}))})};module.exports={eventResults:eventResults,addPointsToEvents:addPointsToEvents,add_event_to_user:add_event_to_user};